(() => {
const C=globalThis.COURSES;
const number=(prompt,value,unit,explanation,tolerance=.02)=>({type:'number',prompt,value,unit,explanation,tolerance});
const classify=(prompt,categories,items,explanation)=>({type:'classify',prompt,categories,items:items.map(([text,category])=>({text,category})),explanation});
const order=(prompt,steps,explanation)=>({type:'order',prompt,steps,explanation});
const matching=(prompt,pairs,explanation)=>({type:'matching',prompt,pairs:pairs.map(([term,definition])=>({term,definition})),explanation});
const multi=(prompt,options,answers,explanation)=>({type:'multi',prompt,options,answers,explanation});
const scenario=(prompt,choices)=>({type:'scenario',prompt,choices:choices.map(([text,feedback,valid])=>({text,feedback,valid}))});
const extras={
comeco:[
{title:'Reconcilie os registros, não só o saldo',body:['Reconciliação é comparar as anotações com o que realmente aconteceu. Um saldo bancário não mostra sozinho quanto está comprometido: uma compra no cartão ainda pode não ter sido paga, e uma transferência entre contas pode parecer uma saída sem ser consumo. Separe a data da compra, a data do pagamento e a categoria. Escolha um método e evite registrar a mesma compra duas vezes.','Comece com uma semana de observação. Confira pequenos gastos em espécie, taxas, compras recorrentes e recebimentos. Se houver diferença entre o registro e o extrato, investigue o lançamento em vez de criar uma categoria genérica para esconder o erro. Depois, use o saldo disponível e os compromissos futuros para decidir o que realmente está livre.'],technique:'Diário de sete dias',steps:['Registre valor, data, categoria e forma de pagamento.','Compare as anotações com extratos e dinheiro em espécie.','Separe transferências próprias e compras ainda não pagas.','Reveja o padrão, não apenas um gasto isolado.'],example:'Exemplo fictício: entram R$ 600; saem R$ 380 em despesas; R$ 100 ficam destinados a uma meta. O saldo financeiro após as despesas é R$ 220, mas só R$ 120 estão livres depois da alocação da meta.',activity:number('Entram R$ 600, você paga R$ 380 e separa R$ 100 para uma meta. Quanto fica livre?',120,'R$','600 − 380 − 100 = 120. Dinheiro guardado para uma meta não é consumo, mas tem um destino definido.')},
{title:'Considere o contexto antes de classificar',body:['A mesma compra pode cumprir funções diferentes. Internet usada para estudar pode ser necessária; uma assinatura adicional apenas para diversão pode ser uma vontade. O nome da categoria não decide por você. Escreva qual necessidade o gasto atende e qual seria o efeito de adiar, reduzir ou substituir essa compra.','Uma pausa antes de comprar ajuda a comparar preço total, uso esperado e alternativas. Compare o produto com o que você já tem e com a meta que deixaria para depois. A técnica não exige um prazo rígido universal: escolha uma pausa suficiente para sair da pressão da propaganda e conferir o orçamento.'],technique:'Pausa e custo de oportunidade',steps:['Nomeie a função da compra.','Compare o custo completo e uma alternativa.','Identifique qual objetivo seria adiado.','Decida depois de conferir o orçamento.'],example:'Exemplo fictício: uma assinatura de R$ 20 por mês custa R$ 240 em 12 meses, se mantiver preço e duração. Perguntar se você usará o serviço ajuda mais que olhar apenas para os R$ 20.',activity:classify('Neste caso, o jovem usa ônibus para ir ao estágio e internet para estudar. Classifique os gastos conforme essa situação.',['Essencial neste caso','Vontade neste caso'],[['Transporte até o estágio','Essencial neste caso'],['Internet para as aulas','Essencial neste caso'],['Assinatura extra de jogos','Vontade neste caso'],['Ingresso para um passeio opcional','Vontade neste caso']],'A classificação depende do contexto descrito; ela não é uma regra universal para qualquer pessoa.')},
{title:'Reserve para o que não acontece todo mês',body:['Despesas anuais e sazonais costumam desaparecer de um orçamento pensado só para o mês atual. Material escolar, manutenção e uma cobrança anual podem ser previstos. Some o valor estimado, verifique quantos meses faltam e forme uma provisão mensal. Provisão é separar gradualmente para um gasto esperado; reserva de emergência protege situações inesperadas.','Você pode usar categorias com limites flexíveis, às vezes chamadas de envelopes. Não precisam ser envelopes físicos: podem ser linhas em um caderno. O limite é uma hipótese de planejamento, não uma autorização para gastar tudo. Na revisão, transfira prioridades com consciência e registre o motivo do ajuste.'],technique:'Envelopes e provisões',steps:['Liste categorias e compromissos.','Inclua despesas menos frequentes.','Defina valores que caibam na renda.','Compare planejado e realizado e ajuste.'],example:'Exemplo fictício: você prevê R$ 240 de material em seis meses. Separar R$ 40 por mês prepara esse pagamento sem depender de um único mês.',activity:number('Um gasto previsto de R$ 240 acontecerá em seis meses. Sem rendimento, qual provisão mensal prepara o valor?',40,'R$','240 ÷ 6 = 40. Esse dinheiro tem finalidade prevista, diferente de uma emergência.')}
],
reserva:[
{title:'Teste se a contribuição cabe na vida real',body:['Uma meta precisa conversar com seu fluxo de renda. Além do preço principal, liste custos de uso, entrega e manutenção. Se o preço for uma estimativa, registre a data e a fonte. Para renda irregular, planeje uma contribuição mínima possível e trate meses melhores como oportunidade de antecipar, sem criar obrigação impossível de manter.','Divida a meta em marcos menores e revise o progresso pelo valor que falta, não por comparação com outras pessoas. Se a contribuição mensal compromete alimentação, transporte ou estudo, mude o prazo ou a alternativa de compra. O plano precisa preservar as necessidades atuais.'],technique:'Meta com três cenários',steps:['Calcule uma contribuição possível.','Teste um prazo menor e outro maior.','Compare o esforço mensal em cada prazo.','Escolha uma combinação sustentável.'],example:'Exemplo fictício: faltam R$ 720. Em seis meses, são R$ 120 por mês; em nove, R$ 80; em doze, R$ 60, sem rendimento.',activity:number('Faltam R$ 720 e você escolhe um prazo de doze meses. Quanto precisa guardar por mês, sem rendimento?',60,'R$','720 ÷ 12 = 60. Aumentar o prazo reduz a contribuição necessária, mantendo a meta nominal.')},
{title:'Planeje também o uso e a reposição',body:['Uma reserva fica mais clara quando existe um critério de uso. Avalie se o gasto é necessário, urgente e inesperado. Uma despesa planejada pertence à provisão ou à meta. Se você usar a reserva, atualize o valor restante e defina como repor, sem transformar a reposição em uma nova fonte de aperto.','Avalie a disponibilidade em diferentes situações: finais de semana, perda de acesso ao aplicativo ou imprevisto fora do horário de resgate. O nome de um produto não garante acesso em qualquer instante. A reserva pode ser organizada em camadas de disponibilidade, compatíveis com custos e segurança. A quantidade de meses é uma escolha individual de planejamento.'],technique:'Critério de uso da reserva',steps:['Descreva quais situações justificam usar.','Confira acesso, horários e riscos.','Registre cada retirada.','Reponha conforme o orçamento permitir.'],example:'Exemplo fictício: essenciais de R$ 700 por mês e uma meta pessoal de quatro meses formam R$ 2.800. A referência não determina o que toda pessoa precisa.',activity:number('No cenário, despesas essenciais são R$ 700 por mês. Para uma referência escolhida de quatro meses, qual o valor da reserva?',2800,'R$','700 × 4 = 2.800. A adequação de quatro meses depende da realidade, da estabilidade de renda e da rede de apoio.')},
{title:'Separe hábito, produto e rendimento',body:['Guardar dinheiro é um comportamento; a caderneta é uma forma de manter recursos. Ao comparar produtos, pense em resultado líquido, liquidez e regras de remuneração. Um produto com rendimento anunciado maior pode não permitir o uso na hora em que sua finalidade exige.','No aniversário da poupança, o rendimento corresponde ao período previsto nas regras. Uma retirada pode alterar o saldo considerado para a remuneração. Confira os depósitos e sua instituição, sem tentar otimizar centavos enquanto assume um risco maior de não conseguir pagar uma necessidade urgente.'],technique:'Checklist de onde guardar',steps:['Escreva a finalidade do dinheiro.','Leia como e quando o rendimento é creditado.','Confira como sacar ou resgatar.','Compare risco e resultado líquido.'],example:'Exemplo fictício: R$ 500 destinados a uma conta que vence amanhã precisam estar disponíveis no prazo. Um ganho potencial não compensa automaticamente perder esse acesso.',activity:matching('Associe o conceito à definição.',''.split('').map(()=>[]),'')}
],
juros:[
{title:'Veja de onde vem cada parcela do montante',body:['Separar principal e juros evita confundir depósito com ganho. Em uma aplicação sem aportes, o principal é o capital inicial. Com aportes, some tudo o que você colocou. O ganho bruto simulado é o saldo final menos esse total. Em um contrato real, confirme os descontos e o fluxo de pagamentos.','Uma taxa pequena repetida por muitos períodos pode produzir um efeito relevante. Esse mesmo mecanismo também pesa contra quem acumula uma dívida. Não use o crescimento composto como promessa de enriquecimento: taxas, custos, tributos e condições podem mudar.'],technique:'Tabela de capitalização',steps:['Comece pelo saldo inicial.','Calcule os juros do período.','Some os juros ao saldo.','Repita usando a nova base.'],example:'Exemplo fictício: R$ 200 a 2% ao mês, sem aporte. Mês 1: R$ 204. Mês 2: R$ 208,08. Mês 3: R$ 212,2416, antes de arredondar.',activity:number('R$ 200 rendem hipoteticamente 2% ao mês por dois meses, sem aportes. Qual é o montante bruto?',208.08,'R$','200 × 1,02² = 208,08. A taxa do segundo mês usa a base já atualizada.')},
{title:'Compare taxas equivalentes e fluxos iguais',body:['Equivalência de taxas é uma comparação para o mesmo regime de capitalização. Uma taxa nominal com outra frequência de capitalização precisa de leitura do contrato; não aplique automaticamente a fórmula de uma taxa efetiva a todo anúncio. Pergunte qual taxa é efetiva e qual o período de composição.','Dois simuladores também podem diferir pela data do aporte, pelos dias usados no ano ou pela inclusão de custos. Compare as hipóteses antes dos resultados. Neste site, a simulação usa taxa anual efetiva convertida para mensal e aportes no final do mês.'],technique:'Padronização da comparação',steps:['Identifique unidade e regime da taxa.','Converta taxas efetivas pelo fator composto.','Iguale o prazo e a data dos aportes.','Confira os descontos considerados.'],example:'Exemplo hipotético: 1% ao mês efetivo corresponde a (1,01¹² − 1) × 100, aproximadamente 12,68% ao ano.',activity:number('Uma taxa efetiva hipotética de 1% ao mês equivale a quantos por cento ao ano? Use duas casas decimais.',12.68,'%','(1,01¹² − 1) × 100 = aproximadamente 12,68%. Somar doze taxas de 1% ignora a composição.')},
{title:'Use sensibilidade para entender o plano',body:['Análise de sensibilidade é mudar uma variável de cada vez e observar o efeito. Isso ajuda a distinguir o impacto de prazo, contribuição e taxa. Escolha hipóteses plausíveis para aprender o mecanismo e inclua um cenário em que o ganho seja zero. Nenhum cenário é uma previsão.', 'Uma projeção bruta pode esconder perda de poder de compra ou despesas do investimento. Descreva cada hipótese ao lado do resultado. Se uma decisão só funciona com uma taxa muito alta, reavalie a viabilidade da contribuição e do prazo.'],technique:'Uma variável de cada vez',steps:['Registre uma simulação de referência.','Mude somente o aporte.','Volte à referência e mude o prazo.','Compare sem transformar hipóteses em promessas.'],example:'Exemplo fictício, sem rendimento: capital de R$ 100 mais R$ 50 por mês durante doze meses totaliza R$ 700.',activity:number('Você começa com R$ 100 e coloca R$ 50 no fim de cada mês durante doze meses. Com taxa zero, qual o saldo?',700,'R$','100 + 12 × 50 = 700. Todo o aumento nesse cenário veio das contribuições.')}
],
economia:[
{title:'Compare a mesma cesta',body:['Um preço só é comparável quando produto, quantidade e qualidade são equivalentes. Trocar uma embalagem por outra menor pode esconder aumento do preço por unidade. Para entender sua cesta, anote quantidade e valor unitário, não apenas o total do recibo.','O índice médio não substitui esse acompanhamento pessoal. Sua rotina pode ter mais transporte, menos aluguel ou uma despesa de saúde específica. Utilize o índice como referência e revise os preços relevantes para seus objetivos.'],technique:'Preço por unidade',steps:['Confira quantidade e apresentação.','Divida preço pela quantidade.','Compare produtos equivalentes.','Atualize o custo da meta.'],example:'Exemplo fictício: 500 g a R$ 10 custam R$ 20 por kg. Uma embalagem de 400 g a R$ 9 custa R$ 22,50 por kg, apesar do preço da embalagem ser menor.',activity:number('Uma embalagem de 400 g custa R$ 9. Qual o preço por quilograma?',22.5,'R$','9 ÷ 0,4 = 22,50. Comparar por unidade evita confundir embalagem mais barata com produto proporcionalmente mais barato.')},
{title:'Separe porcentagem e pontos percentuais',body:['Uma taxa passar de 5% para 6% significa aumento de um ponto percentual. Em termos relativos, a taxa aumentou 20%, pois 1 ÷ 5 = 0,20. Ler essa diferença evita interpretar manchetes como se porcentagens e pontos percentuais fossem a mesma coisa.','No retorno real, use períodos iguais e valores líquidos. A inflação não é um desconto cobrado pela instituição: ela é o ajuste necessário para comparar o que o saldo pode comprar. O valor nominal continua no extrato; o ajuste descreve poder de compra.'],technique:'Retorno real exato',steps:['Use retorno líquido e inflação do mesmo período.','Transforme cada taxa em um fator 1 + taxa.','Divida os fatores.','Subtraia um e expresse em percentual.'],example:'Exemplo fictício: 10% líquidos com 6% de inflação resultam em 1,10 ÷ 1,06 − 1, aproximadamente 3,77% de retorno real.',activity:number('Retorno nominal líquido hipotético de 10% e inflação de 6% no mesmo período. Qual o retorno real, em percentual?',3.77,'%','(1,10 ÷ 1,06 − 1) × 100 ≈ 3,77%. A diferença direta de 4 pontos é apenas aproximação.')},
{title:'Leia a referência, não apenas a sigla',body:['A Selic aparece em política monetária, produtos financeiros e contratos, mas as funções podem ser diferentes. Uma decisão do Copom não transforma automaticamente cada taxa de crédito na mesma taxa. Custos, risco e condições do contrato influenciam a oferta individual.','Percentual do CDI também exige ler prazo e forma de apuração. Quando a referência varia, o ganho final depende da acumulação durante o período. Não compare um percentual de referência anual com uma oferta mensal sem padronizar a unidade.'],technique:'Leitura de uma taxa anunciada',steps:['Identifique qual referência e unidade aparecem.','Diferencie taxa efetiva e percentual da referência.','Confira prazo, liquidez e custos.','Consulte o contrato e a fonte oficial.'],example:'Exemplo didático: um anúncio com “100% do CDI” informa uma proporção de uma referência; não promete lucro de 100% sobre o capital.',activity:multi('Quais informações faltam para avaliar uma oferta que anuncia somente um percentual do CDI?',['Regras de resgate','Emissor e risco de crédito','Prazo e custos aplicáveis','Quantidade de seguidores do anúncio'],[0,1,2],'Emissor, liquidez, prazo e custos ajudam a entender a oferta. Popularidade de uma postagem não substitui condições contratuais.')}
],
credito:[
{title:'Olhe os próximos meses, não só a fatura atual',body:['Uma compra parcelada compromete renda futura. Monte um calendário com a soma de todas as parcelas em cada mês. A fatura atual pode ser baixa enquanto pagamentos de compras novas começam no ciclo seguinte. Considere também despesas que serão pagas fora do cartão.','Se o preço à vista e o parcelado diferem, compare o custo total e a disponibilidade do dinheiro. Anunciar “sem juros” não elimina o custo de abrir mão de um desconto, quando ele existe. A compra também precisa atender uma prioridade do orçamento.'],technique:'Calendário de compromissos',steps:['Liste parcelas com início e fim.','Some o total de cada mês.','Inclua pagamentos fora do cartão.','Teste uma despesa inesperada antes de comprar mais.'],example:'Exemplo fictício: quatro parcelas mensais de R$ 50 mais duas de R$ 35 somam R$ 270 de compromissos no mês em que todas se encontram.',activity:number('Quatro compras têm parcela mensal de R$ 50 e duas têm parcela de R$ 35. Quanto fica comprometido no mês em que todas coincidem?',270,'R$','4 × 50 + 2 × 35 = 270. O orçamento precisa enxergar a soma, não apenas uma parcela.')},
{title:'Padronize as propostas de crédito',body:['Para comparar duas ofertas, confira valor efetivamente recebido, entrada, quantidade e datas de pagamentos, CET e garantias. Uma tarifa descontada na liberação pode diminuir o dinheiro disponível. Uma condição variável também pode impedir prever exatamente todo o custo.', 'Some os desembolsos para entender o total nominal e compare o CET em uma mesma unidade. Não conclua que uma parcela menor é uma oferta mais barata. Avalie o risco de atraso e se há uma alternativa que evite contratar crédito.'],technique:'Matriz de propostas',steps:['Coloque as ofertas lado a lado.','Iguale valor recebido e prazo quando possível.','Leia CET e despesas não incluídas na parcela.','Confirme sustentabilidade no orçamento.'],example:'Exemplo fictício: dez parcelas de R$ 110 totalizam R$ 1.100; vinte parcelas de R$ 65 totalizam R$ 1.300. Aqui, as demais condições são assumidas iguais apenas para praticar a conta.',activity:number('Uma proposta fictícia tem vinte parcelas de R$ 65, sem entrada ou outros custos no exercício. Qual o total nominal pago?',1300,'R$','20 × 65 = 1.300. O total nominal é uma parte da comparação; CET, prazo e condições também importam.')},
{title:'Conheça estratégias sem tratá-las como regra',body:['Priorizar dívidas com juros maiores pode reduzir o custo de juros, mantendo pagamentos necessários nas demais e observadas garantias e consequências. Priorizar saldos menores pode ajudar algumas pessoas a organizar a rotina e manter motivação. Essas estratégias de organização não substituem uma avaliação das condições reais e das despesas essenciais.','Antes de negociar, saiba quanto consegue pagar de forma recorrente. Peça saldo e proposta por canais oficiais, confira custo total e registre o acordo. Um abatimento anunciado pode não representar uma solução sustentável se a parcela continuar acima da sua capacidade.'],technique:'Mapa de dívidas e capacidade de pagamento',steps:['Registre saldo, encargos e consequências do atraso.','Preserve despesas essenciais.','Defina uma parcela possível e compare propostas.','Acompanhe o acordo e o saldo depois dos pagamentos.'],example:'Exemplo fictício: juros de R$ 50 e pagamento de R$ 150 reduzem o principal em R$ 100 no primeiro mês, se não houver outros encargos.',activity:number('No modelo do exercício, dívida de R$ 1.000 a 5% ao mês recebe um pagamento de R$ 150 ao final do primeiro mês. Qual o saldo restante?',900,'R$','1.000 × 1,05 − 150 = 900. R$ 50 pagam os juros e R$ 100 reduzem o saldo principal.')}
],
perfil:[
{title:'Escreva um risco em linguagem concreta',body:['Uma etiqueta de risco fica mais útil quando você descreve um evento. “Risco de crédito” pode significar não receber de volta do emissor; “risco de mercado”, ter de vender quando o preço caiu; “risco de liquidez”, não conseguir sair no prazo necessário. Um mesmo produto pode reunir os três.', 'Separe probabilidade, consequência e capacidade de suportar a perda. Um evento raro pode ser grave se comprometer dinheiro essencial. Essa análise ajuda a formular perguntas antes de escolher um produto.'],technique:'Risco em três perguntas',steps:['O que pode dar errado?','Qual seria o efeito no meu objetivo?','Consigo suportar esse efeito?','Que condição ou alternativa reduz essa exposição?'],example:'Exemplo didático: uma taxa atraente não resolve o problema de um título bloqueado por dois anos quando você precisa da quantia no mês seguinte.',activity:classify('Associe cada evento ao risco principal descrito.',['Crédito','Mercado','Liquidez'],[['O emissor não cumpre o pagamento','Crédito'],['O preço cai antes da venda necessária','Mercado'],['Não há resgate no prazo de que você precisa','Liquidez']],'Os riscos podem coexistir. A classificação identifica o mecanismo principal de cada frase.')},
{title:'Horizonte e capacidade mudam a decisão',body:['Ter mais anos de vida pela frente não torna todo dinheiro disponível para risco alto. A quantia necessária para uma despesa próxima tem horizonte curto, independentemente da idade. Sua experiência também não substitui a capacidade financeira de suportar uma perda.','O questionário da instituição ajuda a avaliar adequação e deve ser respondido sem tentar obter uma categoria mais “avançada”. Situações novas, como perder renda ou assumir dependentes, justificam rever perfil e objetivos. Este site não emite uma classificação oficial.'],technique:'Objetivo, prazo e perda suportável',steps:['Dê um nome à quantia.','Registre quando vai usá-la.','Avalie o efeito de uma perda ou bloqueio.','Responda honestamente ao processo de adequação.'],example:'Exemplo didático: gostar de novidades não muda a necessidade de ter dinheiro para o transporte da próxima semana.',activity:multi('Quais informações ajudam a avaliar a adequação de um investimento?',['Objetivo e prazo','Situação financeira e capacidade de perda','Conhecimento e experiência','Apenas a idade'],[0,1,2],'Objetivos, capacidade financeira, conhecimento e experiência importam. A idade sozinha não determina adequação.')},
{title:'Procure exposições repetidas',body:['Diversificação olha para as fontes de risco, não apenas para a quantidade de nomes. Diferentes produtos podem depender do mesmo grupo financeiro, país, setor ou indexador. Conhecer essa dependência é mais útil que contar ativos.', 'Uma revisão periódica pode identificar concentração criada pela valorização de um ativo ou por novos aportes. Ajustes devem considerar objetivo, custos e tributos; fazer muitas operações pode aumentar despesas sem melhorar o plano. Não há uma divisão universal adequada a todas as pessoas.'],technique:'Mapa de exposições',steps:['Anote emissor, setor, classe e prazo.','Marque fatores que se repetem.','Compare com os objetivos e limites pessoais.','Revise de forma planejada, considerando custos.'],example:'Exemplo fictício: três CDBs do mesmo conglomerado distribuídos por três plataformas ainda concentram crédito no mesmo conglomerado.',activity:scenario('Você encontra três títulos distribuídos por aplicativos diferentes, mas emitidos pelo mesmo conglomerado. O que isso muda na análise?', [['Contar como três emissores independentes','As plataformas são diferentes, mas a obrigação depende do mesmo conglomerado. A concentração não desaparece.',false],['Somar a exposição ao conglomerado','Isso ajuda a compreender o risco compartilhado e os limites de cobertura aplicáveis aos créditos elegíveis.',true],['Considerar que nenhuma análise é necessária','A distribuição por aplicativos não substitui a avaliação de crédito, liquidez e condições.',false]])}
],
bancos:[
{title:'Identifique o credor, o devedor e o distribuidor',body:['O investimento não é automaticamente uma obrigação da plataforma que o apresenta. No comprovante, identifique quem emitiu o título e quem presta o serviço de distribuição. Leia remuneração, prazo, carência, vencimento e regras de resgate antes de confirmar.', 'Uma oferta prefixada permite conhecer a taxa contratada para suas condições, enquanto uma pós-fixada depende de uma referência. Em ambos os casos, resultado líquido e disponibilidade precisam ser avaliados. Um prazo sem resgate pode ser relevante mesmo quando o valor inicial é pequeno.'],technique:'Leitura do comprovante',steps:['Localize emissor e distribuidor.','Identifique regra de remuneração.','Leia prazo e liquidez.','Registre custos e tributação aplicáveis.'],example:'Exemplo fictício: uma aplicação de R$ 1.000 gera R$ 100 de ganho bruto e R$ 20 de desconto hipotético no exercício. O ganho líquido é R$ 80 e o montante líquido, R$ 1.080.',activity:number('Neste exercício, o ganho bruto é R$ 100 e os descontos hipotéticos somam R$ 20. Qual o ganho líquido?',80,'R$','100 − 20 = 80. O desconto é uma hipótese didática, não a indicação da tributação vigente de um produto.')},
{title:'Uma vantagem fiscal não decide sozinha',body:['Tratamento tributário faz parte da comparação, mas as regras precisam ser conferidas para o produto, o investidor e a data. Não compare ganho bruto de uma opção com ganho líquido de outra e conclua que são equivalentes.', 'Carência e vencimento também importam. Uma opção que tenha tratamento tributário vantajoso pode ter taxa menor ou impedir o resgate necessário. Leia as condições atuais da oferta e diferencie títulos bancários de cotas de fundos ligados ao mesmo setor.'],technique:'Comparação líquida e compatível',steps:['Iguale prazo e valores para o exercício.','Aplique apenas descontos realmente pertinentes.','Compare risco e disponibilidade.','Confira regras vigentes antes de decidir.'],example:'Exemplo fictício: oferta A tem ganho líquido de R$ 80; B, de R$ 85, mas o prazo de B não permite uso na data da meta. O maior ganho não resolve a incompatibilidade do prazo.',activity:matching('Associe a sigla à sua natureza.',[['CDB','Título bancário para captação de recursos'],['LCI','Letra ligada ao setor imobiliário'],['LCA','Letra ligada ao agronegócio'],['FII','Cota de fundo de investimento imobiliário']],'LCI e LCA são títulos de instituições financeiras; FII é um fundo, com regras e riscos diferentes.')},
{title:'Some saldo e rendimentos elegíveis',body:['O limite de cobertura considera o conjunto de créditos elegíveis nas regras do FGC. Ao avaliar exposição, lembre-se de que rendimentos incorporados ao saldo podem participar da quantia considerada. Confira instituição associada, conglomerado e o teto global aplicável.', 'A garantia não elimina o processo operacional de pagamento ou a possibilidade de ficar um período sem acesso ao recurso em um evento coberto. Esse aspecto é relevante para uma reserva destinada a urgências. Leia a fonte oficial, e não apenas o selo mostrado numa oferta.'],technique:'Concentração e limites',steps:['Verifique elegibilidade e instituição associada.','Agrupe por instituição ou conglomerado.','Considere os créditos conforme as regras.','Confira limite individual, teto global e processo de pagamento.'],example:'Exemplo fictício: R$ 150 mil e R$ 150 mil em créditos elegíveis do mesmo conglomerado somam R$ 300 mil. O limite ordinário de R$ 250 mil não é multiplicado pelos aplicativos.',activity:classify('Quais destes produtos têm cobertura ordinária do FGC, respeitadas as regras?',['Elegível à garantia ordinária','Sem garantia ordinária'],[['CDB elegível de instituição associada','Elegível à garantia ordinária'],['LCI elegível de instituição associada','Elegível à garantia ordinária'],['Cota de ETF','Sem garantia ordinária'],['Título do Tesouro Direto','Sem garantia ordinária']],'A cobertura depende da natureza do crédito e das condições do FGC; não cobre cotas de fundos ou títulos públicos.')}
],
tesouro:[
{title:'Leia o fluxo de pagamentos',body:['O título precisa ser entendido como um conjunto de regras e datas. Confira aplicação, liquidação, vencimento e eventuais pagamentos periódicos. Dois papéis com nomes parecidos podem ter fluxos diferentes e exigir planejamento diferente.', 'A instituição escolhida pode ter custos e procedimentos próprios. Identifique o título no comprovante e guarde registros. Planejar o uso do dinheiro para uma data não elimina o risco de precisar vender antes; é importante compreender esse cenário antes da compra.'],technique:'Linha do tempo do título',steps:['Identifique o papel e o objetivo.','Marque vencimento e eventos intermediários.','Confira liquidação, custos e resgate.','Teste a hipótese de saída antes do prazo.'],example:'Exemplo didático: um título destinado a renda em várias parcelas tem fluxo diferente de receber um montante único no vencimento.',activity:order('Nesta sequência de estudo, o objetivo vem antes do produto. Organize as etapas.', ['Definir objetivo e data de uso','Entender remuneração e fluxo do título','Conferir custos, riscos e regras de saída','Revisar as condições antes de confirmar'],'A sequência é um roteiro didático; a análise deve continuar sempre que uma condição não ficar clara.')},
{title:'Taxas reais e nominais não são iguais',body:['Em um título híbrido ligado à inflação, o resultado nominal incorpora fatores de inflação e da taxa contratada conforme as regras do papel. Somar as taxas é uma aproximação em um exemplo simples; multiplicar os fatores evidencia o efeito composto.', 'Um fluxo com pagamentos intermediários muda a quantidade que permanece aplicada e pode gerar tributação em momentos distintos. Para comparar, considere o fluxo completo e a finalidade, não somente a taxa exibida.'],technique:'Leitura da remuneração',steps:['Identifique referência e parcela contratada.','Separe nominal e real.','Verifique os eventos de pagamento.','Confira o resultado líquido e o prazo.'],example:'Exemplo hipotético de um período anual: inflação de 5% e taxa real de 4% produzem fator 1,05 × 1,04 = 1,092, ou 9,2% nominal antes de descontos, no modelo do exercício.',activity:number('No exemplo simplificado, inflação de 5% e taxa real de 4% combinam os fatores 1,05 e 1,04. Qual a taxa nominal resultante em percentual?',9.2,'%','(1,05 × 1,04 − 1) × 100 = 9,2%. Este é um exercício matemático, não uma taxa disponível no mercado.')},
{title:'Uma queda no extrato precisa de contexto',body:['Se a taxa exigida pelo mercado muda, o valor de negociação do título pode mudar. Para uma venda antes do vencimento, esse preço de mercado é relevante. Para manter até o vencimento, considere as condições contratadas do título, os custos e os riscos.', 'Registrar o motivo da compra ajuda a reavaliar sem reagir apenas a uma oscilação. Se seu objetivo ou prazo mudou, faça uma nova análise. Não conclua que manter sempre ou vender sempre seja uma regra correta para todo caso.'],technique:'Duas perguntas sobre uma oscilação',steps:['Estou avaliando preço de mercado ou vencimento?','Preciso vender antes da data planejada?','Quais custos e regras entram nessa saída?','Meu objetivo e minha capacidade mudaram?'],example:'Exemplo fictício: preço de compra R$ 1.000 e preço de venda R$ 950 significam perda bruta de R$ 50, antes de qualquer custo.',activity:number('No cenário, você compra por R$ 1.000 e vende antecipadamente por R$ 950. Qual a perda bruta em reais?',50,'R$','1.000 − 950 = 50. Uma regra de remuneração para o vencimento não garante o mesmo resultado na venda antecipada.')}
],
bolsa:[
{title:'Preço por ação não mede o tamanho do negócio',body:['O preço unitário é apenas uma parte da avaliação. Quantidade de ações, situação financeira e direitos do papel importam. Uma ação que custa poucos reais não é necessariamente uma participação barata em relação ao valor econômico do negócio.', 'Separe opinião, hipótese e fato. Relatórios de resultados e documentos da companhia ajudam a conferir informação. Uma análise responsável registra limitações e a possibilidade de o cenário esperado não acontecer.'],technique:'Ficha do negócio',steps:['Descreva como a empresa gera receita.','Leia resultados, dívida e caixa.','Identifique riscos e governança.','Compare a avaliação com suas hipóteses e limitações.'],example:'Exemplo fictício: dez ações a R$ 20 custam R$ 200, antes de despesas; a R$ 18, a posição vale R$ 180.',activity:number('Dez ações custam R$ 20 cada e depois são vendidas a R$ 18 cada. Sem custos ou proventos, qual a perda total?',20,'R$','10 × (20 − 18) = 20. O preço pode variar e produzir perdas mesmo em empresas conhecidas.')},
{title:'Leia os direitos, não só o código',body:['Espécies de ações e estatutos podem estabelecer direitos diferentes. Direito de voto, preferências econômicas e proteção em eventos societários precisam ser lidos nos documentos pertinentes, sem presumir que todos os papéis tenham regras iguais.', 'Indicadores também exigem contexto. Um lucro pontual ou uma mudança de estrutura pode distorcer uma comparação. Aprender um indicador não dispensa entender a atividade, o período e a origem dos números.'],technique:'Checagem do documento',steps:['Confira a espécie da ação.','Leia direitos e preferências.','Observe período e origem dos indicadores.','Compare contexto e riscos, além de um número isolado.'],example:'Exemplo didático: duas empresas com a mesma relação entre preço e lucro podem ter dívidas, perspectivas e riscos bastante diferentes.',activity:matching('Relacione as palavras ao significado.',[['ON','Ação ordinária, com direito de voto'],['PN','Ação preferencial, com direitos definidos nas regras'],['Receita','Valor gerado pelas atividades conforme a apuração'],['Governança','Regras e práticas de direção e controle da companhia']],'Os direitos específicos devem ser conferidos no estatuto e na legislação. Um indicador isolado não decide a adequação do investimento.')},
{title:'Olhe o retorno total',body:['Receber dinheiro de uma distribuição é apenas um componente do resultado. A mudança no valor da posição também participa da avaliação. Custos, tributos e reinvestimentos precisam ser considerados quando você analisa o resultado líquido.', 'Um dividend yield alto pode ser consequência de um preço baixo após uma queda, de pagamento extraordinário ou de outros fatores. Pergunte se o fluxo é sustentável e qual risco acompanha a atividade. A renda futura não é garantida por uma distribuição passada.'],technique:'Resultado em duas partes',steps:['Some os valores recebidos no período.','Compare o valor final da posição com o inicial.','Considere custos e tributos pertinentes.','Avalie sustentabilidade e riscos do fluxo.'],example:'Exemplo fictício: R$ 100 investidos, preço final de R$ 90 e R$ 5 recebidos resultam em R$ 95 de valor total bruto.',activity:number('Uma posição inicial de R$ 100 termina em R$ 90 e distribui R$ 5. Qual o retorno total bruto em percentual?',-5,'%','(90 + 5 − 100) ÷ 100 × 100 = −5%. O fluxo recebido não elimina a perda de valor da posição.')}
],
fundos:[
{title:'O documento explica a carteira',body:['A política de investimento indica o que o fundo pode fazer e o regulamento descreve condições relevantes. Prestadores de serviço, taxas e prazos variam. Uma carteira com vários ativos não significa automaticamente que os riscos sejam variados.', 'Leia a composição e compare com a proposta do fundo. Identifique custos que reduzem o patrimônio ou o resultado do investidor. Uma cota negociada em bolsa pode exigir venda a outro investidor para sair, em vez de um resgate direto a qualquer momento.'],technique:'Leitura em quatro partes',steps:['Leia política e regulamento.','Veja a carteira e concentrações.','Confira taxas e despesas.','Entenda a saída e o prazo do dinheiro.'],example:'Exemplo didático: o nome “imobiliário” indica uma área de atuação, mas o fundo pode ter imóveis, títulos e outras exposições previstas em sua política.',activity:order('Organize um roteiro didático para estudar um fundo.', ['Identificar política e regulamento','Examinar carteira e riscos','Conferir taxas e condições de saída','Comparar com seu objetivo e prazo'],'A ordem organiza o estudo; a decisão depende da leitura completa e da situação individual.')},
{title:'A distribuição depende dos ativos',body:['Em um fundo com imóveis, vacância e contratos podem afetar receitas; em um fundo ligado a títulos, capacidade dos devedores e condições financeiras também importam. Informações de relatórios ajudam a compreender a origem do fluxo, sem garantir seu valor futuro.', 'Observe concentração e despesas, não apenas o rendimento distribuído por cota. Para avaliar resultado, considere distribuições e preço da participação no mesmo período. O papel de uma cota no plano depende do risco e do acesso que você precisa.'],technique:'De onde vem o rendimento?',steps:['Identifique o tipo de ativo da carteira.','Leia receitas, despesas e fatores de risco.','Observe concentração e mudanças do período.','Avalie fluxo e variação da cota juntos.'],example:'Exemplo fictício: cota comprada por R$ 100, valor final de R$ 95 e R$ 3 distribuídos geram R$ 98 de valor total bruto.',activity:number('Uma cota custa R$ 100, termina em R$ 95 e distribui R$ 3 no período. Qual o retorno total bruto em percentual?',-2,'%','(95 + 3 − 100) ÷ 100 × 100 = −2%. Receber distribuições não torna o resultado automaticamente positivo.')},
{title:'Um índice pode carregar concentração',body:['Índices têm critérios de composição e pesos. Um ETF com muitas posições ainda pode depender principalmente de poucas empresas ou de um setor. Leia a referência e a composição para identificar o tipo de exposição que você está adquirindo.', 'Diferenças entre o fundo e a referência podem surgir de custos e de outros aspectos de acompanhamento. ETFs de classes diferentes podem ter riscos, tributação e política de distribuição distintos. Confira o documento do fundo específico.'],technique:'Mapa do índice',steps:['Identifique a referência.','Leia os critérios e maiores pesos.','Confira custos e acompanhamento.','Compare exposição, liquidez e objetivo.'],example:'Exemplo didático: um índice de um único setor pode reunir muitas empresas e continuar exposto a um choque comum naquele setor.',activity:multi('O que conferir antes de entender a proposta de um ETF?',['Qual índice ele busca acompanhar','Composição e concentração','Taxas e condições de negociação','Só o preço da cota'],[0,1,2],'Índice, composição e custos ajudam a entender a exposição. O preço unitário da cota, sozinho, não descreve a carteira.')}
],
digital:[
{title:'Proteção de acesso faz parte do risco',body:['Riscos digitais podem ocorrer mesmo quando o preço do ativo sobe. A conta do prestador, a integridade do dispositivo e a recuperação de acesso são condições diferentes da avaliação econômica. Uma transferência para endereço incorreto pode ser difícil ou impossível de reverter.', 'Entenda as responsabilidades de custódia e nunca entregue senhas ou palavras de recuperação a um contato desconhecido. Atualize sistemas e use canais oficiais. Segurança reduz certas exposições, mas não elimina oscilação, perda financeira ou falha do prestador.'],technique:'Checklist de acesso',steps:['Confira o canal oficial e a natureza do serviço.','Entenda custódia e recuperação de acesso.','Proteja dispositivo e autenticação.','Leia riscos antes de transferir qualquer recurso.'],example:'Exemplo didático: perder a chave de acesso é um mecanismo de risco distinto de uma queda na cotação do ativo.',activity:classify('Associe o evento ao tipo principal de problema.',['Oscilação de preço','Custódia e acesso','Fraude'],[['A cotação cai intensamente','Oscilação de preço'],['Você perde a chave necessária para usar os ativos','Custódia e acesso'],['Um contato falso pede senha para liberar um ganho','Fraude']],'Preço, custódia e fraude são fontes diferentes de perda. Proteger o acesso não garante retorno positivo.')},
{title:'Hipótese não é certeza de execução',body:['Médias móveis e regiões de suporte ou resistência organizam dados e hipóteses. O mercado pode mudar, atravessar uma região ou negociar com liquidez diferente da esperada. Uma estratégia precisa considerar perdas, custos e o efeito de execuções diferentes do preço desejado.', 'Um simulador pode ensinar o mecanismo, mas não reproduz integralmente atraso, spread, liquidez e pressão emocional. Antes de confiar em uma alegação de lucro, pergunte qual período foi medido, quais custos foram incluídos e se perdas e limitações foram divulgadas. Este curso não fornece sinais ou uma estratégia para operar.'],technique:'Leitura crítica de um resultado',steps:['Confira período e condições da medição.','Inclua custos e perdas.','Observe execução e limitações da simulação.','Não trate um padrão passado como garantia futura.'],example:'Exemplo fictício: lucro bruto de R$ 40 e custos de R$ 50 produzem perda de R$ 10 antes de eventual efeito tributário.',activity:number('Operações do exercício têm lucro bruto total de R$ 40 e custos de R$ 50. Qual o resultado antes de eventual tributação?',-10,'R$','40 − 50 = −10. Acertar movimentos de preço não basta para ganhar depois dos custos.')},
{title:'Verifique por fora do anúncio',body:['Links recebidos em mensagens podem copiar aparência de uma instituição. Confira o endereço por um canal independente e consulte o órgão competente. Uma pessoa mostrar um registro ou logotipo também não prova que a operação oferecida esteja autorizada.', 'Uma boa fonte distingue fato de opinião, mostra data e método e informa limitações. Relação comercial ou comissão pode influenciar a apresentação. Transparência não elimina risco, mas ajuda você a interpretar a informação e formular perguntas.'],technique:'Três verificações independentes',steps:['Confirme endereço e identidade fora do anúncio.','Confira autorização para o serviço pertinente.','Compare a informação com uma fonte primária.','Interrompa a decisão se condições continuarem obscuras.'],example:'Exemplo didático: uma promessa de ganho alto garantido com pagamento imediato exige verificação; enviar uma quantia pequena também pode expor ao golpe.',activity:multi('Quais situações são sinais de alerta?',['Promessa de retorno alto sem risco','Pedido de senha ou palavra de recuperação','Pressão para transferir agora','Explicação clara de custos e riscos'],[0,1,2],'Promessas, pedidos de credenciais e pressão são sinais de alerta. Explicar custos e riscos é parte da transparência, sem garantir lucro.')}
],
plano:[
{title:'Desenhe uma sequência que preserve o básico',body:['Seu primeiro plano pode começar com poucas linhas: entradas, necessidades, compromissos, uma margem e uma meta. A renda pode ser pequena ou irregular, e isso altera o que é possível. Reavaliar o prazo de um objetivo costuma ser mais útil que comprometer dinheiro essencial para tentar acelerar retornos.', 'Começar com pouco também exige olhar os custos. Uma tarifa fixa pode consumir uma parte importante de um valor pequeno. Use aprendizagem e organização como primeiros resultados, sem medir sua evolução pela quantia que outra pessoa investe.'],technique:'Plano de uma página',steps:['Registre a situação atual.','Defina necessidades e compromissos.','Escolha uma meta possível e uma margem.','Revise a sequência conforme sua realidade.'],example:'Exemplo fictício: R$ 20 por mês durante cinco meses formam R$ 100 sem rendimento. O hábito deve caber no orçamento, não prejudicar necessidades.',activity:order('Organize a sequência didática de um primeiro plano.', ['Observar renda, gastos e dívidas','Proteger despesas essenciais','Definir uma reserva inicial e uma meta possível','Estudar produtos compatíveis com prazo e risco'],'Uma sequência ajuda a organizar decisões; a realidade pode exigir ajustes e apoio.')},
{title:'Compare serviço e produto separadamente',body:['Uma instituição pode ter bom atendimento e oferecer um produto incompatível com sua finalidade. Uma plataforma pode distribuir títulos de emissores diferentes. Compare o serviço que você usa e, separadamente, as condições de cada aplicação.', 'Informe-se sobre autorização, custos, acesso, atendimento e recuperação da conta. Ao avaliar um anúncio de rendimento, entenda qual produto gera aquele resultado. O site não faz um ranking de instituições: ele oferece critérios para você investigar.'],technique:'Matriz de critérios pessoais',steps:['Liste o que o serviço precisa permitir.','Confira autorização e canais de suporte.','Analise o produto e seu emissor.','Compare custo, prazo, risco e acesso.'],example:'Exemplo didático: um bônus inicial não resolve uma tarifa recorrente ou a impossibilidade de resgatar na data da meta.',activity:multi('Quais critérios são úteis para comparar instituições e seus produtos?',['Autorização e segurança','Custos e atendimento','Emissor, prazo e liquidez do produto','Apenas um bônus de indicação'],[0,1,2],'Serviço, segurança e condições de cada produto precisam ser avaliados. Um incentivo comercial não descreve tudo isso.')},
{title:'Aprenda a revisar sem operar por impulso',body:['Uma revisão é uma conferência de objetivos, compromissos e condições. Ela não exige trocar de produto ou fazer uma operação sempre. Observe se suas metas, necessidades ou compreensão mudaram; registre o motivo de uma alteração para poder avaliá-la depois.', 'Guarde documentos e consulte obrigações vigentes. Automatizar registros pode ajudar, mas não substitui conferir lançamentos e proteger dados. Seu caderno neste site fica no navegador e não é sincronizado; exporte um arquivo se quiser manter uma cópia.'],technique:'Revisão semanal e mensal',steps:['Confira registros e próximos pagamentos.','Compare plano e realidade.','Ajuste uma decisão concreta quando necessário.','Guarde os documentos e a justificativa.'],example:'Plano de prática: uma revisão curta semanal para gastos; uma revisão mensal para metas, reserva e mudanças da vida.',activity:scenario('Sua renda diminuiu e a contribuição para uma meta passou a comprometer o transporte. Qual ajuste respeita o objetivo do planejamento?', [['Manter a contribuição e faltar ao compromisso essencial','O plano deixou de caber. Preservar o transporte exige reavaliar a contribuição ou o prazo.',false],['Rever contribuição e prazo da meta','Esse ajuste adapta o plano à renda e preserva a necessidade atual. A meta pode continuar com outro prazo.',true],['Buscar uma promessa de lucro para compensar','Uma promessa de retorno não resolve a falta de renda e pode criar novas perdas.',false]])}
]
};
extras.reserva[2].activity=matching('Associe os conceitos.',[['Poupar','Separar uma parte do dinheiro que entra'],['Poupança','Nome de um produto financeiro'],['Liquidez','Possibilidade de transformar o investimento em dinheiro'],['Provisão','Valor separado para um gasto esperado']],'Hábito, produto, acesso e planejamento de gasto são conceitos distintos.');
const capstones={
comeco:{title:'Um mês com R$ 600: ajuste o plano',intro:'Uma boa organização também precisa lidar com mudanças. Neste caso, você decide como absorver uma despesa sem perder de vista o que já era importante.',text:['No cenário fictício, entram R$ 600. Transporte custa R$ 120, alimentação R$ 180, lazer R$ 80 e uma meta recebe R$ 100. As despesas de consumo somam R$ 380; a meta tem outro destino e deixa R$ 120 livres. Separar essas duas leituras evita chamar poupança de gasto, sem fingir que a quantia está livre para qualquer compra.','Se aparecer um gasto necessário de R$ 90, existem alternativas. Usar o saldo livre deixa R$ 30; rever lazer ou o prazo da meta também pode abrir espaço, com efeitos diferentes. Compare necessidade, urgência, prazo e consequências. O exemplo não estabelece que toda pessoa deve guardar a mesma porcentagem ou ter as mesmas despesas.','Depois da escolha, atualize o orçamento e registre o motivo. Planejado e realizado são informações diferentes: o plano estima o futuro, enquanto os registros contam o que aconteceu. Ao revisar, busque um aprendizado concreto, como incluir uma despesa esquecida ou ajustar um limite, em vez de apenas julgar o resultado como sucesso ou fracasso.'],example:'600 − 120 − 180 − 80 − 100 = R$ 120 livres. Se a nova despesa de R$ 90 for paga com essa margem: 120 − 90 = R$ 30.',steps:['Identifique o saldo realmente livre.','Avalie a necessidade e a urgência da mudança.','Compare efeitos na meta e no lazer.','Atualize o plano e registre sua decisão.'],question:'Quanto fica livre depois de pagar R$ 90 com a margem de R$ 120?',options:['R$ 30','R$ 120','R$ 210'],correct:0,explanation:'120 − 90 = 30. A meta de R$ 100 permanece separada neste caminho.',activity:scenario('Apareceu a despesa necessária de R$ 90. Escolha um caminho e veja o efeito no exemplo.',[['Usar R$ 90 do saldo livre','Ficam R$ 30 livres, preservando o valor previsto para a meta e o lazer. Essa alternativa cabe nas condições descritas.',true],['Rever lazer e usar parte da margem','Você precisa definir quanto reduzir e atualizar o orçamento. Também é possível nas condições do caso, respeitando suas prioridades.',true],['Rever o prazo da meta','A contribuição pode mudar, e o prazo precisa ser recalculado. Isso é um ajuste de planejamento, não uma falha moral.',true],['Assumir que a despesa não conta no orçamento','O pagamento precisa aparecer nos registros; ignorá-lo esconderia o saldo real.',false]]),sources:['budget']},
reserva:{title:'Separe reserva, provisão e meta',intro:'Três quantias podem ficar guardadas e ter finalidades diferentes. Separá-las ajuda você a usar cada uma na situação adequada.',text:['Reserva protege imprevistos necessários e quedas de renda. Provisão prepara um gasto esperado, como material para o próximo período de estudo. Meta prepara um objetivo escolhido, como um curso ou equipamento. Usar a mesma quantia para prometer três pagamentos cria um plano que não fecha.','No exercício, R$ 300 pertencem a uma provisão de material e R$ 500 a uma reserva. Uma compra planejada não deve ser chamada de emergência só porque o prazo chegou. Confira o custo e o prazo para formar a provisão gradualmente; preserve o critério de uso da reserva.','Essa separação pode ser feita em um caderno ou em controles do serviço financeiro que você utiliza. Ela não exige abrir várias contas ou comprar vários produtos. O acesso e o risco de cada quantia precisam conversar com a data e a finalidade. A organização mental ajuda, mas o registro é o que permite conferir se o total existe.'],example:'Exemplo fictício: reserva de R$ 500 + provisão de R$ 300 + meta de R$ 200 = R$ 1.000 guardados, com três destinos que não devem ser contados duas vezes.',steps:['Nomeie a finalidade de cada quantia.','Separe gasto esperado de imprevisto.','Confira data de uso e acesso ao dinheiro.','Revise o saldo após qualquer retirada.'],question:'Material escolar com compra prevista para daqui a três meses pertence principalmente a…',options:['Provisão de gasto esperado','Emergência inevitável','Ganho garantido'],correct:0,explanation:'O gasto foi previsto, então pode ser preparado como provisão.',activity:classify('Classifique as situações deste caso.',['Reserva','Provisão','Meta'],[['Reparo necessário inesperado','Reserva'],['Material escolar previsto para o próximo período','Provisão'],['Curso opcional que você quer realizar','Meta']],'A classificação organiza a finalidade. Condições individuais podem alterar o planejamento.'),sources:['budget','risk']},
juros:{title:'Leia uma projeção com senso crítico',intro:'Uma projeção só pode ser interpretada quando as hipóteses estão visíveis. Aprenda a separar contribuição, ganho e incerteza.',text:['Registre capital, taxa, unidade, prazo e momento dos aportes. Se a taxa mudar, o cenário matemático já será outro. Duas projeções com saldos diferentes podem ter sido calculadas corretamente com premissas diferentes. O primeiro passo é comparar as condições.','No exercício sem rendimento, R$ 100 iniciais e R$ 50 ao mês por 24 meses formam R$ 1.300. Com taxa positiva hipotética, a diferença é um ganho bruto simulado. Ainda faltam custos, tributação aplicável e ajuste pela inflação para avaliar o poder de compra do resultado.','Crie uma tabela de cenários alterando uma variável de cada vez. Um objetivo que só cabe em uma hipótese otimista deve ser revisto. A projeção serve para aprender e planejar, não para prometer um resultado ao leitor ou justificar risco incompatível com dinheiro essencial.'],example:'Sem rendimento: 100 + 24 × 50 = R$ 1.300. O saldo é formado somente por contribuições.',steps:['Escreva todas as hipóteses.','Separe o dinheiro aportado do ganho.','Inclua os descontos pertinentes na análise real.','Compare cenários e reavalie a meta.'],question:'O total que você depositou ao longo do período é…',options:['Total aportado','Sempre lucro','Inflação'],correct:0,explanation:'Aportes são contribuições próprias; não devem ser contados como rentabilidade.',activity:number('R$ 100 iniciais mais R$ 50 mensais por 24 meses, com taxa zero. Qual o total?',1300,'R$','100 + 24 × 50 = 1.300.'),sources:['math']},
economia:{title:'Atualize uma meta pelo custo relevante',intro:'O preço do que você deseja pode mudar de forma diferente do índice médio. Planejar também envolve revisar o custo do objetivo.',text:['Uma meta nominal de R$ 1.000 pode deixar de cobrir a compra se o preço aumentar. No exercício, uma variação hipotética de 5% transforma esse custo em R$ 1.050. Isso não é a divulgação do IPCA atual; é uma conta para aprender o mecanismo.','Para saber o que acontece com seu dinheiro, compare renda, rendimento líquido e inflação em períodos iguais. Se o custo específico da compra mudou mais que o índice, atualize também o preço que você realmente precisará pagar. Um indicador agregado não é uma promessa sobre todo item.','Uma revisão pode levar a aumentar contribuição, prazo ou mudar a alternativa de compra. Antes de decidir, confira se o novo preço inclui a mesma quantidade e qualidade. A informação bem comparada é a base para ajustar o plano sem atribuir toda variação a uma única causa.'],example:'Exemplo hipotético: 1.000 × 1,05 = R$ 1.050. Faltam R$ 50 a mais se o custo da compra subir exatamente 5%.',steps:['Confira o preço atual do objetivo.','Compare condições equivalentes.','Atualize o valor que falta.','Recalcule contribuição ou prazo.'],question:'Uma inflação positiva menor significa necessariamente que os preços caíram?',options:['Não','Sim','Só para estudantes'],correct:0,explanation:'Preços podem continuar subindo em ritmo menor.',activity:number('No exemplo, um objetivo de R$ 1.000 aumenta 5%. Qual o novo custo?',1050,'R$','1.000 × 1,05 = 1.050.'),sources:['inflation','ipca']},
credito:{title:'Compare acordos que cabem no mês',intro:'Renegociar precisa transformar a dívida em um compromisso compreensível e possível, não apenas trocar o nome da cobrança.',text:['Peça a proposta completa por um canal oficial. Registre saldo anterior, entrada, número de parcelas, valor, taxas e total nominal. Uma parcela menor pode estar associada a um prazo maior e a um custo total maior; confira os dois lados.', 'No caso fictício, um acordo oferece dez parcelas de R$ 110 e outro vinte de R$ 65, sem entrada ou despesas adicionais no exercício. Os totais são R$ 1.100 e R$ 1.300. Essa conta não avalia todas as condições de um contrato real. CET, valor recebido, garantias e consequências também precisam ser comparados.', 'Verifique a capacidade de pagamento depois de preservar as despesas essenciais. Se nenhuma proposta cabe, procurar novas condições é mais responsável que assumir um acordo que tende a ser descumprido. Registre documentos e acompanhe cada pagamento pelo canal adequado.'],example:'10 × 110 = R$ 1.100; 20 × 65 = R$ 1.300. O segundo total é R$ 200 maior neste exercício.',steps:['Confira a proposta e a identidade do credor.','Compare custo, prazo e condições.','Teste as parcelas no orçamento.','Guarde o acordo e acompanhe pagamentos.'],question:'Uma parcela menor prova que a dívida ficou mais barata?',options:['Não','Sim','Sempre'],correct:0,explanation:'Prazo, total pago, CET e demais condições também importam.',activity:number('Qual a diferença entre R$ 1.300 e R$ 1.100 de total nominal?',200,'R$','1.300 − 1.100 = 200.'),sources:['credit','math']},
perfil:{title:'Faça uma ficha de decisão',intro:'Objetivo, prazo, risco e acesso podem ser organizados antes de você olhar uma lista de produtos.',text:['Dê um nome à finalidade, registre a data de uso e avalie o efeito de uma perda ou bloqueio. Depois, transforme essas informações em condições: acesso necessário, oscilação suportável e capacidade de assumir crédito. Essas perguntas ajudam a reduzir opções incompatíveis.', 'Uma quantia usada em duas semanas exige uma análise diferente de uma finalidade distante. A idade não apaga o prazo da necessidade. Uma pessoa pode aceitar risco emocionalmente e não conseguir suportar seu efeito financeiro.', 'Estude as condições do produto, responda ao processo de adequação da instituição e registre dúvidas. Esta ficha é um exercício educativo e não substitui um perfil oficial ou uma análise individual. Revise quando objetivo, prazo ou situação financeira mudar.'],example:'Caso fictício: dinheiro do transporte das próximas semanas não está disponível para ser perdido ou bloqueado, mesmo que seu titular goste de acompanhar novidades.',steps:['Escreva finalidade e data.','Avalie perda e falta de acesso.','Leia os riscos e condições da alternativa.','Revise a adequação com informação suficiente.'],question:'Qual informação vem antes de escolher um produto para uma meta?',options:['Objetivo e prazo de uso','Popularidade da postagem','Uma taxa isolada'],correct:0,explanation:'A finalidade e o prazo ajudam a avaliar se o produto atende à necessidade.',activity:order('Organize a ficha didática de decisão.', ['Definir finalidade e prazo','Avaliar perda e disponibilidade necessárias','Estudar risco, custos e condições do produto','Reavaliar adequação e registrar dúvidas'],'A ficha organiza o estudo; não transforma uma aplicação em algo sem risco.'),sources:['profile','risk']},
bancos:{title:'Compare duas ofertas fictícias',intro:'O maior número de uma propaganda não contém todas as respostas. Use uma comparação que mostre o que cada oferta permite.',text:['Neste caso, a opção A permite resgate em dias úteis e a B bloqueia o recurso por dois anos. Não estamos citando ofertas reais, taxas disponíveis ou bancos específicos. O objetivo é aprender a testar uma condição contra uma finalidade.', 'Se a finalidade exige o recurso em dois meses, a indisponibilidade de B é uma incompatibilidade importante. O ganho potencial só deve ser comparado depois de compreender acesso, risco, custos e tratamento tributário pertinente. A aplicação mais rentável numa hipótese não é necessariamente a que atende à meta.', 'Leia documentos, identifique emissor e distribuidor e confira eventual garantia conforme suas regras. Uma comparação educativa não é uma recomendação de instituição. O resultado da decisão depende da situação individual e das condições vigentes.'],example:'Exemplo fictício: você precisa do dinheiro em dois meses; um título sem resgate por dois anos não oferece o acesso necessário para essa finalidade.',steps:['Defina a finalidade.','Compare liquidez e vencimento.','Analise risco e resultado líquido.','Confira documentos e regras aplicáveis.'],question:'A maior taxa resolve uma incompatibilidade de prazo?',options:['Não','Sim','Se o anúncio for conhecido'],correct:0,explanation:'Uma taxa maior não permite resgatar um dinheiro que está bloqueado.',activity:scenario('Você precisa da quantia em dois meses. A oferta B não permite resgate por dois anos. O que fazer no estudo?', [['Marcar B como incompatível com esse prazo','A indisponibilidade é incompatível com a finalidade. Você ainda precisa estudar outras condições das opções restantes.',true],['Ignorar o prazo e escolher só pela taxa','O ganho anunciado não resolve o acesso necessário em dois meses.',false]]),sources:['bank','risk','fgc']},
tesouro:{title:'Planeje a data e um imprevisto',intro:'Entender o vencimento é importante, mas também é preciso considerar o que acontece se o plano mudar.',text:['Leia remuneração, fluxo e vencimento, e descreva a hipótese de saída antecipada. O programa pode permitir solicitação de resgate conforme suas regras, mas o preço e a liquidação precisam ser compreendidos. Solicitar saída não significa receber o retorno originalmente considerado para o vencimento.', 'No caso fictício, uma venda por R$ 950 após compra por R$ 1.000 gera perda bruta de R$ 50. Esse exemplo não prevê o comportamento de um título específico. Ele mostra por que preço de mercado e remuneração contratada são leituras diferentes.', 'A adequação depende de prazo, objetivo, custo e risco. Verifique as regras atuais do título e da instituição antes de confirmar. Uma boa ficha registra também o que você faria se precisasse da quantia antes do planejado, sem impor uma decisão automática a toda oscilação.'],example:'1.000 − 950 = R$ 50 de perda bruta na venda do cenário.',steps:['Leia as condições para o vencimento.','Entenda preço e regras de venda antes dele.','Confira custos e liquidação.','Compare com prazo e situações de mudança.'],question:'Qual valor orienta uma venda antecipada no programa?',options:['Preço de mercado conforme as regras','Sempre o preço da compra','Um lucro garantido pelo FGC'],correct:0,explanation:'O resgate antecipado considera preço de mercado e condições do programa.',activity:matching('Associe conceito e leitura.',[['Vencimento','Data e condições finais previstas para o título'],['Marcação a mercado','Valor atualizado pela negociação de mercado'],['Liquidação','Procedimento e prazo de efetivação financeira'],['Taxa contratada','Regra acertada na compra, com as condições do papel']],'As quatro informações participam da análise; não são sinônimos.'),sources:['treasury','products']},
bolsa:{title:'Estude o negócio e o resultado completo',intro:'Uma decisão sobre ações exige entender o que a empresa faz e como uma mudança no negócio pode afetar seu investimento.',text:['Registre atividade, fontes de receita, dívida, geração de caixa e riscos relevantes. Consulte documentos e diferencie informação do período de expectativas. Uma empresa conhecida ou um preço baixo por ação não elimina a possibilidade de perda.', 'Avalie direitos do papel e o resultado total. Distribuições e valorização podem participar do ganho, mas também pode haver queda de preço ou redução dos resultados do negócio. Sustentabilidade do fluxo e risco precisam ser considerados juntos.', 'No exercício, uma posição de R$ 100 termina em R$ 90 e distribui R$ 5; o valor total bruto é R$ 95. O objetivo é aprender a leitura, sem avaliar uma companhia real. Custos e tributação aplicável podem alterar o resultado líquido.'],example:'90 + 5 = R$ 95; em relação a R$ 100, perda bruta de 5%.',steps:['Descreva atividade e riscos.','Leia direitos e documentos.','Calcule resultado com preço e distribuições.','Considere custos e a adequação ao objetivo.'],question:'Receber dividendos garante retorno total positivo?',options:['Não','Sim','Sempre em ações conhecidas'],correct:0,explanation:'A variação no valor da posição também participa do retorno.',activity:number('R$ 100 iniciais, R$ 90 de valor final e R$ 5 distribuídos. Qual o valor total bruto ao fim?',95,'R$','90 + 5 = 95. O total é menor que o inicial.'),sources:['stocks','tax']},
fundos:{title:'Uma carteira por dentro de uma cota',intro:'Estudar um fundo significa abrir a ideia por trás da cota: política, ativos, custos, riscos e regras de saída.',text:['Leia o regulamento e a política para entender o que a gestão pode fazer. Confira composição, concentração e prestadores. Uma cota representa participação em uma carteira; seu nome comercial não substitui esses documentos.', 'FIIs e ETFs não são a mesma classe de produto. Os primeiros se relacionam a empreendimentos e ativos imobiliários conforme sua política; os segundos buscam acompanhar uma referência. Ambos podem ter oscilação de preço e condições específicas de negociação ou saída.', 'A diversificação da carteira pode reduzir algumas exposições e manter outras. Um fundo concentrado em um setor pode sofrer com eventos comuns àquele setor. A análise exige compreender as fontes de risco e a forma de resultado, não apenas a quantidade de posições ou uma distribuição passada.'],example:'Exemplo didático: possuir várias posições de um único setor não elimina a dependência daquele setor.',steps:['Leia política e regulamento.','Abra a composição e os maiores pesos.','Confira taxas e saídas.','Compare riscos e finalidade da sua quantia.'],question:'Muitas posições de um só setor eliminam o risco desse setor?',options:['Não','Sim','Se o preço da cota for baixo'],correct:0,explanation:'Exposições podem compartilhar um fator de risco, mesmo com vários nomes.',activity:multi('Que informações fazem parte de uma análise de fundo?',['Política e carteira','Taxas e despesas','Concentração e regras de saída','Somente o nome comercial'],[0,1,2],'Documentos e exposição são essenciais para compreender a proposta; o nome não contém todas as condições.'),sources:['fii','etf','risk']},
digital:{title:'Analise uma promessa antes de agir',intro:'A pressão por uma resposta rápida pode impedir uma conferência básica. Crie um roteiro que devolva tempo à sua decisão.',text:['No caso fictício, uma mensagem promete retorno alto garantido, solicita Pix imediato e pede segredo. Esses sinais não são uma oportunidade que precisa ser testada com dinheiro. São motivos para interromper a decisão e verificar identidade e condições por canais independentes.', 'Registros e autorizações precisam corresponder ao serviço oferecido; ter uma instituição legítima citada num anúncio não prova que o anunciante a represente. Não compartilhe senha, código ou palavras de recuperação. Consulte alertas dos órgãos competentes.', 'A mesma leitura crítica vale para conteúdo educativo ou comercial: autor, data, método, interesses e limitações. Um gráfico de operações ou depoimento isolado não mostra necessariamente o resultado de todas as pessoas ou a inclusão dos custos. Este curso não oferece sinais de compra ou promessa de renda.'],example:'Caso fictício: “ganho garantido sem risco, mande Pix agora” é uma frase de alerta, não uma taxa a ser colocada no orçamento.',steps:['Pare a transferência ou a entrega de dados.','Verifique identidade por um canal independente.','Confira autorização e alertas pertinentes.','Compare informações e preserve provas se houver suspeita.'],question:'Como agir diante de pedido de senha para liberar um ganho?',options:['Não compartilhar e verificar por canais oficiais','Enviar só parte da senha','Testar com uma quantia pequena'],correct:0,explanation:'Credenciais e palavras de recuperação não devem ser entregues a um contato que pede liberação de ganhos.',activity:order('Organize este roteiro de proteção.', ['Interromper pagamento e entrega de credenciais','Conferir a identidade em canal independente','Consultar autorização e alertas oficiais','Preservar provas e procurar orientação se necessário'],'Este é um roteiro educativo para reduzir exposição, não uma garantia de recuperação de valores.'),sources:['fraud','crypto','trade']},
plano:{title:'Seu plano de 30 dias',intro:'Depois de conhecer os conceitos, o próximo passo é criar uma rotina que você consiga manter e revisar.',text:['Na primeira semana, observe entradas e saídas e confira registros. Na segunda, escolha uma meta e defina uma contribuição possível. Na terceira, investigue condições e dúvidas relevantes, usando fontes confiáveis. Na quarta, compare plano e realidade e ajuste uma decisão. Os prazos são um roteiro de prática, não uma exigência universal.', 'Registre o que você decidiu e por quê. Mudanças de renda, família, prazo e necessidade podem alterar o plano. Revisar não exige investir ou operar a cada semana: uma boa decisão pode ser manter a quantia acessível ou estudar antes de fazer qualquer operação.', 'Seu caderno ajuda a guardar observações e perguntas neste navegador. Ele não sincroniza com outros aparelhos; exporte uma cópia se quiser preservar seus registros. Guarde também comprovantes e informes das instituições e confira obrigações vigentes em fontes oficiais.'],example:'Plano educativo: observar → definir uma meta possível → pesquisar condições → revisar o que aconteceu.',steps:['Escolha uma rotina curta de registro.','Defina uma meta e uma margem realistas.','Anote dúvidas e consulte fontes.','Faça uma revisão e guarde os documentos.'],question:'Uma revisão precisa gerar uma operação financeira nova?',options:['Não','Sim','Sempre que houver notícia'],correct:0,explanation:'Revisar é conferir adequação e condições; manter ou estudar pode ser a decisão pertinente.',activity:order('Organize o roteiro educativo de 30 dias.', ['Observar e conferir registros','Definir uma meta possível','Pesquisar condições e registrar dúvidas','Revisar plano e realidade'],'Os passos podem se adaptar à vida de cada pessoa. O roteiro não determina um produto ou uma meta universal.'),sources:['budget','profile','tax']}
};
C.forEach(c=>{c.lessons.forEach((l,i)=>{const e=extras[c.id][i];l.deep={title:e.title,paragraphs:e.body};l.technique={title:e.technique,steps:e.steps};l.worked=e.example;l.activities=[{type:'quiz',prompt:l.question,options:l.options,correct:l.correct,explanation:l.explanation},e.activity];l.id=`${c.id}:${i}`;});const e=capstones[c.id];c.lessons.push({...e,deep:{title:'Use o raciocínio, não apenas uma resposta',paragraphs:['Antes de conferir, escreva as condições e a conta que você usou. Se outra alternativa parecer possível, identifique qual prioridade ou hipótese mudou. Um exercício pode ter uma solução didática para as condições dadas, sem decidir toda situação real da mesma maneira.']},technique:{title:'Da informação à decisão',steps:e.steps},worked:e.example,activities:[{type:'quiz',prompt:e.question,options:e.options,correct:e.correct,explanation:e.explanation},e.activity,{type:'reflection',prompt:'O que você levaria desse caso para uma situação da sua vida? Use valores fictícios se preferir.',explanation:'Esta anotação é pessoal e não recebe uma classificação automática de certo ou errado.'}],id:`${c.id}:3`});c.lessons.forEach(l=>{const words=[l.intro,...l.text,...l.deep.paragraphs,l.example,l.worked,...l.technique.steps].join(' ').split(/\s+/).length;l.minutes=Math.max(5,Math.ceil(words/170)+4);});});
C[0].title='Orçamento na vida real';C[1].title='Metas e reserva';
globalThis.MODULES=[{name:'Organizar o presente',description:'Orçamento, metas, juros e crédito para entender o dia a dia.',ids:['comeco','reserva','juros','economia','credito']},{name:'Entender os investimentos',description:'Antes de escolher um produto, compreenda prazo, retorno e risco.',ids:['perfil','bancos','tesouro','bolsa','fundos']},{name:'Escolher com consciência',description:'Informação, segurança e um plano que acompanha sua realidade.',ids:['digital','plano']}];
globalThis.SOURCES.budgetbook=['Banco Central · Caderno de Educação Financeira','https://www.bcb.gov.br/pre/pef/port/caderno_cidadania_financeira.pdf'];
})();
